//
// G09-R2 — durable generation candidate proposals.
//
// A candidate is a PROPOSAL: generated bytes are committed to the existing
// `CreativeAssetStore` (one canonical row per content hash) and this store
// keeps per-project proposal metadata plus stable operation receipts. A
// candidate never mutates the media project until an explicit accept runs the
// ordinary media CAS/intent transaction.
//
// The store root is the accepted generation's explicit artifact root
// (`<acceptedRoot>/FloeAgent/MediaProjects/Candidates/<projectID>`); there is
// no Application Support convenience root, no absolute caller path and no
// second project database. Candidate bytes live under the same artifact root
// in `MediaProjects/Generated` so both records and bytes survive a restart.
import Foundation
import FloeCore
import FloeAndroidWorkbench
#if canImport(Darwin)
import Darwin
#elseif canImport(Glibc)
import Glibc
#endif

public struct G09R2CandidateRecord: Codable, Sendable, Equatable {
    public var candidateID: String
    public var projectID: UUID
    public var kind: G09R2GenerationKind
    public var modelDisplayName: String?
    public var createdAt: Date
    public var byteCount: Int64
    public var sha256: String
    /// Safe path relative to the accepted artifact root (never absolute).
    public var relativePath: String
    public var assetID: UUID
    public var mimeType: String
    public var metadata: MediaAssetMetadata?
    /// Image request identity, nil for video candidates.
    public var requestID: String?
    /// Durable video job identity, nil for image candidates.
    public var jobID: String?
    public var state: G09R2CandidateState
    public var acceptOpID: String?
    public var acceptRevision: Int64?
    public var acceptedAssetID: UUID?
    public var acceptedRelativePath: String?
    public var rejectOpID: String?
    public var staleReason: String?

    public init(
        candidateID: String, projectID: UUID, kind: G09R2GenerationKind,
        modelDisplayName: String?, createdAt: Date, byteCount: Int64,
        sha256: String, relativePath: String, assetID: UUID,
        mimeType: String, metadata: MediaAssetMetadata?,
        requestID: String?, jobID: String?,
        state: G09R2CandidateState = .pending,
        acceptOpID: String? = nil, acceptRevision: Int64? = nil,
        acceptedAssetID: UUID? = nil, acceptedRelativePath: String? = nil,
        rejectOpID: String? = nil, staleReason: String? = nil
    ) {
        self.candidateID = candidateID
        self.projectID = projectID
        self.kind = kind
        self.modelDisplayName = modelDisplayName
        self.createdAt = createdAt
        self.byteCount = byteCount
        self.sha256 = sha256
        self.relativePath = relativePath
        self.assetID = assetID
        self.mimeType = mimeType
        self.metadata = metadata
        self.requestID = requestID
        self.jobID = jobID
        self.state = state
        self.acceptOpID = acceptOpID
        self.acceptRevision = acceptRevision
        self.acceptedAssetID = acceptedAssetID
        self.acceptedRelativePath = acceptedRelativePath
        self.rejectOpID = rejectOpID
        self.staleReason = staleReason
    }

    public var dto: G09R2CandidateDTO {
        G09R2CandidateDTO(
            candidateID: candidateID,
            projectID: projectID,
            kind: kind,
            modelDisplayName: modelDisplayName,
            createdAt: createdAt,
            byteCount: byteCount,
            sha256: sha256,
            relativePath: relativePath,
            requestID: requestID,
            state: state)
    }
}

/// Stable operation receipt. `payloadHash` binds a replay to the exact
/// operation identity/semantics; a reused opID with different content is
/// refused instead of silently returning the wrong receipt.
public struct G09R2CandidateReceipt: Codable, Sendable, Equatable {
    public var opID: String
    public var kind: String
    public var subjectID: String
    public var payloadHash: String
    public var revision: Int64?
    public var createdAt: Date

    public init(opID: String, kind: String, subjectID: String,
                payloadHash: String, revision: Int64? = nil,
                createdAt: Date = Date()) {
        self.opID = opID
        self.kind = kind
        self.subjectID = subjectID
        self.payloadHash = payloadHash
        self.revision = revision
        self.createdAt = createdAt
    }
}

private struct G09R2CandidateIndex: Codable {
    var schemaVersion: Int = 1
    var candidates: [G09R2CandidateRecord] = []
    var receipts: [String: G09R2CandidateReceipt] = [:]
    /// requestID → exact dismiss operation.
    var dismissals: [String: G09R2CandidateReceipt] = [:]
    /// video jobID → delivered candidateID.
    var deliveries: [String: String] = [:]
}

/// One candidate store per accepted artifact root. All writes are serialized
/// by this actor and land with a same-directory atomic replace; a crash never
/// leaves a partially written index.
public actor G09R2CandidateStore {
    public static let maximumCandidatesPerProject = 200
    public static let maximumReceiptsPerProject = 400

    private let artifactRoot: URL
    private let fileManager = FileManager.default

    public init(artifactRoot: URL) {
        self.artifactRoot = artifactRoot.standardizedFileURL
    }

    public nonisolated var candidatesDirectoryPath: String {
        artifactRoot.appendingPathComponent("MediaProjects/Candidates", isDirectory: true).path
    }

    public nonisolated var generatedDirectoryPath: String {
        artifactRoot.appendingPathComponent("MediaProjects/Generated", isDirectory: true).path
    }

    /// Owned staging directory for one request/job download-or-batch. The
    /// owner token is bounded to the same alphabet as operation IDs.
    public nonisolated func incomingDirectoryURL(ownerID: String) -> URL? {
        guard G09CreativeWire.safeOperationID(ownerID), ownerID.count <= 80 else {
            return nil
        }
        let base = artifactRoot
            .appendingPathComponent("MediaProjects/Generated/Incoming", isDirectory: true)
            .appendingPathComponent(ownerID, isDirectory: true)
            .standardizedFileURL
        guard base.path.hasPrefix(artifactRoot.path + "/") else { return nil }
        return base
    }

    public nonisolated func containedURL(relativePath: String) -> URL? {
        guard G09CreativeAssetHost.safeRelativePath(relativePath),
              !relativePath.isEmpty else { return nil }
        let target = artifactRoot.appendingPathComponent(relativePath).standardizedFileURL
        guard target.path.hasPrefix(artifactRoot.path + "/") else { return nil }
        return target
    }

    // MARK: - Reads

    public func candidates(projectID: UUID) throws -> [G09R2CandidateDTO] {
        try load(projectID: projectID).candidates
            .sorted { $0.createdAt < $1.createdAt }
            .map(\.dto)
    }

    public func record(projectID: UUID, candidateID: String) throws
        -> G09R2CandidateRecord? {
        try load(projectID: projectID).candidates.first {
            $0.candidateID == candidateID
        }
    }

    public func candidateForRequest(projectID: UUID, requestID: String) throws
        -> G09R2CandidateRecord? {
        try load(projectID: projectID).candidates.first {
            $0.requestID == requestID
        }
    }

    public func candidateForJob(projectID: UUID, jobID: String) throws
        -> G09R2CandidateRecord? {
        let index = try load(projectID: projectID)
        if let delivered = index.deliveries[jobID] {
            return index.candidates.first { $0.candidateID == delivered }
        }
        return index.candidates.first { $0.jobID == jobID }
    }

    public func receipt(projectID: UUID, opID: String) throws
        -> G09R2CandidateReceipt? {
        try load(projectID: projectID).receipts[opID]
    }

    public func dismissal(projectID: UUID, requestID: String) throws
        -> G09R2CandidateReceipt? {
        try load(projectID: projectID).dismissals[requestID]
    }

    // MARK: - Writes

    /// Writes/updates one candidate. The candidate identity is unique per
    /// project; an identical rewrite is a no-op, a conflicting one is refused.
    public func upsert(_ candidate: G09R2CandidateRecord) throws {
        guard G09CreativeWire.safeOperationID(candidate.candidateID) else {
            throw G09CreativeError.invalidPayload("invalidCandidateID")
        }
        var index = try load(projectID: candidate.projectID)
        if let existing = index.candidates.first(where: {
            $0.candidateID == candidate.candidateID
        }) {
            if existing != candidate, existing.state != candidate.state {
                // Only the state/accept fields may change after insertion.
                var merged = existing
                merged.state = candidate.state
                merged.acceptOpID = candidate.acceptOpID
                merged.acceptRevision = candidate.acceptRevision
                merged.acceptedAssetID = candidate.acceptedAssetID
                merged.acceptedRelativePath = candidate.acceptedRelativePath
                merged.rejectOpID = candidate.rejectOpID
                merged.staleReason = candidate.staleReason
                index.candidates[index.candidates.firstIndex(where: {
                    $0.candidateID == candidate.candidateID
                })!] = merged
            }
        } else {
            guard index.candidates.count < Self.maximumCandidatesPerProject else {
                throw G09R2Error(.generationUnavailable, detail: "candidateLimit")
            }
            index.candidates.append(candidate)
        }
        try save(index, projectID: candidate.projectID)
    }

    public func setState(
        projectID: UUID, candidateID: String, state: G09R2CandidateState,
        acceptOpID: String? = nil, acceptRevision: Int64? = nil,
        acceptedAssetID: UUID? = nil, acceptedRelativePath: String? = nil,
        rejectOpID: String? = nil, staleReason: String? = nil
    ) throws -> G09R2CandidateRecord {
        var index = try load(projectID: projectID)
        guard let position = index.candidates.firstIndex(where: {
            $0.candidateID == candidateID
        }) else {
            throw G09R2Error(.candidateNotFound)
        }
        index.candidates[position].state = state
        if let acceptOpID { index.candidates[position].acceptOpID = acceptOpID }
        if let acceptRevision {
            index.candidates[position].acceptRevision = acceptRevision
        }
        if let acceptedAssetID {
            index.candidates[position].acceptedAssetID = acceptedAssetID
        }
        if let acceptedRelativePath {
            index.candidates[position].acceptedRelativePath = acceptedRelativePath
        }
        if let rejectOpID { index.candidates[position].rejectOpID = rejectOpID }
        if let staleReason { index.candidates[position].staleReason = staleReason }
        try save(index, projectID: projectID)
        return index.candidates[position]
    }

    public func recordReceipt(_ receipt: G09R2CandidateReceipt,
                              projectID: UUID) throws {
        var index = try load(projectID: projectID)
        if let existing = index.receipts[receipt.opID] {
            guard existing == receipt else {
                throw G09CreativeError.invalidPayload("intentMismatch")
            }
            return
        }
        if index.receipts.count >= Self.maximumReceiptsPerProject {
            // Reclaim only old receipt entries; candidate records are never
            // dropped here.
            let ordered = index.receipts.values.sorted { $0.createdAt < $1.createdAt }
            for old in ordered.prefix(max(1, ordered.count / 4)) {
                index.receipts.removeValue(forKey: old.opID)
            }
        }
        index.receipts[receipt.opID] = receipt
        try save(index, projectID: projectID)
    }

    public func recordDismissal(_ receipt: G09R2CandidateReceipt,
                                projectID: UUID, requestID: String) throws {
        var index = try load(projectID: projectID)
        if let existing = index.dismissals[requestID] {
            if existing.opID != receipt.opID {
                // A second dismiss is idempotent for the same request; keep
                // the first exact operation as the durable receipt.
                return
            }
            return
        }
        index.dismissals[requestID] = receipt
        try save(index, projectID: projectID)
    }

    public func recordDelivery(projectID: UUID, jobID: String,
                               candidateID: String) throws {
        var index = try load(projectID: projectID)
        if let existing = index.deliveries[jobID], existing != candidateID {
            throw G09CreativeError.invalidPayload("deliveryIdentityMismatch")
        }
        index.deliveries[jobID] = candidateID
        try save(index, projectID: projectID)
    }

    // MARK: - Files

    /// Content-addressed generated path. Identical bytes always reuse the
    /// exact same file, so a duplicate provider output or a retry never
    /// creates an aliasing copy.
    public nonisolated static func generatedRelativePath(
        sha256: String, preferredName: String
    ) -> String? {
        guard G09CreativeAssetHost.validDigest(sha256) else { return nil }
        let clean = G09CreativeAssetHost.safeDisplayName(preferredName)
        let suffix = (clean as NSString).pathExtension.lowercased()
        let allowed = suffix.unicodeScalars.allSatisfy {
            CharacterSet.alphanumerics.contains($0)
        }
        let fileExtension = allowed && (1...8).contains(suffix.utf8.count)
            ? suffix : "bin"
        return "MediaProjects/Generated/\(sha256.lowercased()).\(fileExtension)"
    }

    /// Commits verified generated bytes into the generated store. Existing
    /// identical bytes are reused; a conflicting existing file is refused.
    public func commitGeneratedFile(
        data: Data, preferredName: String, expectedSHA256: String
    ) throws -> String {
        guard let relative = Self.generatedRelativePath(
            sha256: expectedSHA256, preferredName: preferredName) else {
            throw G09CreativeError.invalidPayload("invalidFileName")
        }
        guard let target = containedURL(relativePath: relative) else {
            throw G09CreativeError.storageUnavailable
        }
        try ensureDirectory(target.deletingLastPathComponent())
        if fileManager.fileExists(atPath: target.path) {
            guard let size = try? target.resourceValues(forKeys: [.fileSizeKey]).fileSize,
                  Int64(size) == Int64(data.count),
                  let digest = try? FloeDigest.sha256Hex(ofFileAt: target),
                  digest.caseInsensitiveCompare(expectedSHA256) == .orderedSame else {
                throw G09CreativeError.assetDigestMismatch
            }
            return relative
        }
        let temporary = target.deletingLastPathComponent()
            .appendingPathComponent(".\(UUID().uuidString).tmp")
        do {
            try data.write(to: temporary, options: [])
            try Self.flushFile(temporary)
            guard !fileManager.fileExists(atPath: target.path) else {
                throw G09CreativeError.outcomeUnknown
            }
            try fileManager.moveItem(at: temporary, to: target)
            try Self.flushDirectory(target.deletingLastPathComponent())
        } catch let typed as G09CreativeError {
            try? fileManager.removeItem(at: temporary)
            throw typed
        } catch {
            try? fileManager.removeItem(at: temporary)
            throw G09CreativeError.writeFailed
        }
        guard let digest = try? FloeDigest.sha256Hex(ofFileAt: target),
              digest.caseInsensitiveCompare(expectedSHA256) == .orderedSame else {
            try? fileManager.removeItem(at: target)
            throw G09CreativeError.assetDigestMismatch
        }
        return relative
    }

    /// Moves a fully received provider download into the generated store
    /// without loading it into memory. The source is an owned staging file.
    public func commitGeneratedFile(
        from staging: URL, preferredName: String,
        expectedSHA256: String, expectedBytes: Int64
    ) throws -> String {
        guard let relative = Self.generatedRelativePath(
            sha256: expectedSHA256, preferredName: preferredName) else {
            throw G09CreativeError.invalidPayload("invalidFileName")
        }
        guard let target = containedURL(relativePath: relative) else {
            throw G09CreativeError.storageUnavailable
        }
        try ensureDirectory(target.deletingLastPathComponent())
        if fileManager.fileExists(atPath: target.path) {
            guard let size = try? target.resourceValues(forKeys: [.fileSizeKey]).fileSize,
                  Int64(size) == expectedBytes,
                  let digest = try? FloeDigest.sha256Hex(ofFileAt: target),
                  digest.caseInsensitiveCompare(expectedSHA256) == .orderedSame else {
                throw G09CreativeError.assetDigestMismatch
            }
            try? fileManager.removeItem(at: staging)
            return relative
        }
        do {
            try fileManager.moveItem(at: staging, to: target)
            try Self.flushDirectory(target.deletingLastPathComponent())
        } catch {
            throw G09CreativeError.writeFailed
        }
        guard let size = try? target.resourceValues(forKeys: [.fileSizeKey]).fileSize,
              Int64(size) == expectedBytes,
              let digest = try? FloeDigest.sha256Hex(ofFileAt: target),
              digest.caseInsensitiveCompare(expectedSHA256) == .orderedSame else {
            try? fileManager.removeItem(at: target)
            throw G09CreativeError.assetDigestMismatch
        }
        return relative
    }

    /// Exact project-media copy destination for adoption. The target is under
    /// the trusted project root; existing identical bytes are reused.
    public nonisolated static func projectMediaTarget(
        rootURL: URL, assetID: UUID, displayName: String
    ) -> URL? {
        let display = G09CreativeAssetHost.safeDisplayName(displayName)
        guard !display.isEmpty else { return nil }
        let base = rootURL.standardizedFileURL
        let target = base.appendingPathComponent(
            "Workbench/Assets/\(assetID.uuidString.lowercased())-\(display)")
            .standardizedFileURL
        guard target.path.hasPrefix(base.path + "/") else { return nil }
        return target
    }

    public nonisolated static func verifyCandidateFile(
        _ url: URL, byteCount: Int64, sha256: String
    ) -> Bool {
        guard let size = try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize,
              Int64(size) == byteCount,
              let digest = try? FloeDigest.sha256Hex(ofFileAt: url) else {
            return false
        }
        return digest.caseInsensitiveCompare(sha256) == .orderedSame
    }

    // MARK: - Index IO

    private func indexURL(projectID: UUID) -> URL {
        artifactRoot
            .appendingPathComponent("MediaProjects/Candidates", isDirectory: true)
            .appendingPathComponent(projectID.uuidString.lowercased(), isDirectory: true)
            .appendingPathComponent("index.json", isDirectory: false)
    }

    private func load(projectID: UUID) throws -> G09R2CandidateIndex {
        let url = indexURL(projectID: projectID)
        guard fileManager.fileExists(atPath: url.path) else {
            return G09R2CandidateIndex()
        }
        let data: Data
        do {
            data = try Data(contentsOf: url)
        } catch {
            throw G09CreativeError.storageUnavailable
        }
        guard data.count <= 8 * 1024 * 1024 else {
            throw G09CreativeError.projectTooLarge
        }
        do {
            let decoded = try G09CreativeWire.decoder()
                .decode(G09R2CandidateIndex.self, from: data)
            guard decoded.schemaVersion == 1 else {
                throw G09CreativeError.unsupportedSchema
            }
            return decoded
        } catch let typed as G09CreativeError {
            throw typed
        } catch {
            throw G09CreativeError.corruptProject
        }
    }

    private func save(_ index: G09R2CandidateIndex, projectID: UUID) throws {
        let url = indexURL(projectID: projectID)
        try ensureDirectory(url.deletingLastPathComponent())
        let data: Data
        do {
            data = try G09CreativeWire.encoder().encode(index)
        } catch {
            throw G09CreativeError.writeFailed
        }
        guard data.count <= 8 * 1024 * 1024 else {
            throw G09CreativeError.projectTooLarge
        }
        let temporary = url.deletingLastPathComponent()
            .appendingPathComponent(".index-\(UUID().uuidString).tmp")
        do {
            try data.write(to: temporary, options: [])
            try Self.flushFile(temporary)
            if fileManager.fileExists(atPath: url.path) {
                _ = try fileManager.replaceItemAt(url, withItemAt: temporary)
            } else {
                try fileManager.moveItem(at: temporary, to: url)
            }
            try Self.flushDirectory(url.deletingLastPathComponent())
        } catch {
            try? fileManager.removeItem(at: temporary)
            throw G09CreativeError.writeFailed
        }
    }

    private func ensureDirectory(_ url: URL) throws {
        do {
            try fileManager.createDirectory(at: url, withIntermediateDirectories: true)
        } catch {
            throw G09CreativeError.storageUnavailable
        }
    }

    nonisolated static func flushFile(_ url: URL) throws {
        #if canImport(Darwin) || canImport(Glibc)
        let descriptor = open(url.path, O_RDONLY)
        guard descriptor >= 0 else { throw G09CreativeError.writeFailed }
        defer { close(descriptor) }
        guard fsync(descriptor) == 0 else { throw G09CreativeError.writeFailed }
        #endif
    }

    nonisolated static func flushDirectory(_ url: URL) throws {
        #if canImport(Darwin)
        let fd = open(url.path, O_RDONLY)
        guard fd >= 0 else { throw G09CreativeError.writeFailed }
        defer { close(fd) }
        guard fsync(fd) == 0 else { throw G09CreativeError.writeFailed }
        #elseif canImport(Glibc)
        let fd = open(url.path, O_RDONLY)
        guard fd >= 0 else { throw G09CreativeError.writeFailed }
        defer { close(fd) }
        guard fsync(fd) == 0 else { throw G09CreativeError.writeFailed }
        #endif
    }
}
